def apply_content(pages):
    result=[];seen=set()
    for slug,title,kicker,desc,items in pages:
        result.append((slug,*CONTENT[slug]) if slug in CONTENT else (slug,title,kicker,desc,items))
        seen.add(slug)
    result.extend((slug,*value) for slug,value in CONTENT.items() if slug not in seen)
    return result
